```json
{
  "root_causes": [
    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name AS pod, metric, count(*) AS n, avg(value) AS avg_v, min(value) AS mn, max(value) AS mx FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'recommendation%' AND metric IN ('k8s.container.ready','k8s.container.restarts') GROUP BY 1,2", "claim": "Recommendation pod reports container not ready (ready=0) across the abnormal window, with restarts climbing from 2 to 6 (normal: 1)."},
        {"kind": "trace", "sql": "SELECT service_name, count(*) AS n FROM abnormal_traces WHERE service_name = 'recommendation' GROUP BY 1", "claim": "Recommendation emits no spans in the abnormal window, versus 115 spans in the normal window."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) AS n, avg(duration)/1e6 AS avg_ms FROM abnormal_traces WHERE service_name = 'frontend' AND span_name LIKE 'recommendation.Recommendation/GetRecommendations' AND attr_span_kind = 'Client' GROUP BY 1,2", "claim": "All 171 frontend calls to GetRecommendations return Error in about 0.02 ms, i.e. immediate connection failure."}
      ]
    }
  ],
  "propagation": [
    {"from": "recommendation", "to": "frontend", "evidence": [
      {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code AS sc, count(*) AS n FROM abnormal_traces WHERE service_name = 'frontend' AND span_name = 'HTTP /recommendations' GROUP BY 1,2,3,4,5", "claim": "Frontend HTTP /recommendations returns 500 for all 171 requests in the abnormal window, versus 490 successful in normal."}
    ]}
  ]
}
```

